mapper.insert:
INSERT INTO PAYMENT_HISTORY (
    PAYMENT_ID
  , USER_ID
  , PG_TRANSACTION_ID
  , PAYMENT_KEY
  , AMOUNT
  , STATUS
  , APPROVED_AT
  , RAW_RESPONSE
  , REG_ID
) VALUES (
    PAYMENT_HISTORY_SEQ.NEXTVAL
  , #{userId}
  , #{pgTransactionId}
  , #{paymentKey}
  , #{amount}
  , #{status}
  , #{approvedAt, jdbcType=TIMESTAMP}
  , #{rawResponse, jdbcType=CLOB}
  , #{userId}
)
